    const KM_DAYS = {Sun:'អាទិត្យ',Mon:'ចន្ទ',Tue:'អង្គារ',Wed:'ពុធ',Thu:'ព្រហស្បតិ៍',Fri:'សុក្រ',Sat:'សៅរ៍'};
    const khmerDigits = value => String(value).replace(/\d/g, d => '០១២៣៤៥៦៧៨៩'[d]);
    function khmerDate(date, options){const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:TIME_ZONE,year:'numeric',month:'numeric',day:'numeric',weekday:'short'}).formatToParts(new Date(date)).map(part=>[part.type,part.value]));return [options.weekday&&'ថ្ងៃ'+KM_DAYS[p.weekday],options.day&&khmerDigits(p.day),options.month&&KM_MONTHS[p.month-1],options.year&&khmerDigits(p.year)].filter(Boolean).join(' ');}
