    const formatTime = date => new Intl.DateTimeFormat(locale(),{timeZone:TIME_ZONE,hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(date));
    const dateInCambodia = () => new Intl.DateTimeFormat('en-CA',{timeZone:TIME_ZONE,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
    const appointmentDate = a => new Date(`${a.date}T${a.time}:00+07:00`);
