    function renderMap(){return `<section class="card map-panel"><div class="map-header"><h3>${esc(t('cityOverview'))}</h3><span class="pill">${FACILITIES.length} ${esc(t('centres'))}</span></div><div class="map-real photo ph-map" role="group" aria-label="${esc(t('cityOverview'))}">${MAP_LABELS.map(([key,kind,lat,lon])=>`<span class="map-label ${kind}" style="${mapPosition(lat,lon)}" aria-hidden="true">${esc(t(key))}</span>`).join('')}${FACILITIES.map(f=>`<button class="map-pin ${selectedFacility===f.id?'active':''}" style="${mapPosition(f.lat,f.lon)}" data-action="map-pin" data-id="${f.id}" aria-label="${esc(tr(f.name))}"><span class="pin-dot"></span><span class="pin-label">${esc(t(f.city))}</span></button>`).join('')}<span class="map-attrib">${esc(t('mapCredit'))}</span></div><div class="map-footer"><p class="tiny muted" style="margin-bottom:8px">${esc(t('mapExplanation'))}</p><a class="btn btn-text btn-small" href="https://www.openstreetmap.org/#map=7/12.3/104.8" target="_blank" rel="noopener noreferrer">${icon('external')}${esc(t('liveMap'))}</a></div></section>`;}
    function facilityCard(f){const saved=state.savedFacilities.includes(f.id);return `<article class="card facility-card ${selectedFacility===f.id?'selected':''}" id="facility-${f.id}">${photo(f.id,'facility-media')}<span class="pill on-photo">${icon('pin')}${esc(t(f.city))}</span><button class="bookmark on-photo media-action ${saved?'saved':''}" data-action="save-facility" data-id="${f.id}" aria-label="${esc(t('saveFacility'))}" aria-pressed="${saved}">${icon('bookmark')}</button><div class="facility-body"><h3>${esc(tr(f.name))}</h3><p>${esc(tr(f.address))}</p><div class="service-tags">${f.services.map(s=>`<span class="pill blue">${esc(t(s))}</span>`).join('')}</div><p class="tiny hours">${icon('clock')}<span>${esc(tr(f.hours))}</span></p><div class="row wrap"><a class="btn btn-primary btn-small" href="tel:${f.phone}">${icon('phone')}${esc(t('call'))}</a><a class="btn btn-light btn-small" href="https://www.google.com/maps/search/?api=1&amp;query=${encodeURIComponent(f.query)}" target="_blank" rel="noopener noreferrer">${icon('map')}${esc(t('directions'))}</a></div><div class="verification"><span>${esc(f.displayPhone)}</span><span>${esc(t('checked'))}: ${esc(formatDate(CHECKED))}</span><span><a href="${f.url}" target="_blank" rel="noopener noreferrer">${esc(t('officialWebsite'))}${icon('external')}</a>${f.serviceUrl?` · <a href="${f.serviceUrl}" target="_blank" rel="noopener noreferrer">${esc(t('allServices'))}${icon('external')}</a>`:''}</span></div></div></article>`;}
