    function renderCentres(){const f=filters.centres;return pageHead('centresTitle','centresSub')+notice('facilityNotice','warning')+`<div class="toolbar">${search('centres','searchCentres')}<div class="row wrap"><label><span class="screen-reader">${esc(t('allCities'))}</span><select class="filter" data-select="city">${['all','phnompenh','siemreap','kampot'].map(k=>`<option value="${k}" ${f.city===k?'selected':''}>${esc(t(k==='all'?'allCities':k))}</option>`).join('')}</select></label><label><span class="screen-reader">${esc(t('allServices'))}</span><select class="filter" data-select="service">${['all','maternal','children','general'].map(k=>`<option value="${k}" ${f.service===k?'selected':''}>${esc(t(k==='all'?'allServices':k))}</option>`).join('')}</select></label><button class="filter ${f.saved?'active':''}" data-action="saved-facilities" aria-pressed="${f.saved}">${esc(t('savedOnly'))}</button></div></div><div class="map-layout">${renderMap()}<div class="facility-list" id="centres-results">${facilityResultsMarkup()}</div></div>${footer()}`;}
