    function newsResultsMarkup(){const list=newsResults();return list.length?list.map(storyCard).join(''):empty('noResults','noResultsSub','news',button('clearFilters','clear-filters','data-kind="news"','btn-soft'));}
    function renderNews(){return pageHead('newsTitle','newsSub')+notice('newsNotice')+`<div class="toolbar">${search('news','searchNews')}${categoryButtons('news',['all','health','hygiene','climate','women','saved'])}</div><div class="article-grid" id="news-results">${newsResultsMarkup()}</div>${footer()}`;}
